-- BMW i3 (I01) Range Extender (REx) variants: seed generated by the import-car skill from
-- docs/intake/research/bmw-i3-i01-rex.md (research passes 1/2/4/5, Martin's decisions
-- 2026-11-15). Reviewed by Martin 2026-11-15 ("Yes, drop tyres, run").
--
-- CHANGE FROM THE REVIEWED DRAFT (Martin, 2026-11-15): the tyre-size section was removed.
-- catalog_tire_sizes is empty for the whole catalog (the pure-EV i3 configurations have no rows
-- either), and the draft stored the axle inside the size text ("155/70 R19 (front)") because
-- the table has no axle column. Tyre data waits for its own agreed format; the REx sizes stay in
-- the research doc (section 2b: i3 REx 155/70 R19 front / 175/60 R19 rear, i3s REx 175/55 R20 /
-- 195/50 R20). The post-condition check for tyre rows was removed with it.
--
-- REQUIRES 20261115100000_vocab_erev_euro6d_temp_secondary_consumption.sql to have run first
-- (adds hybrid_type='EREV', emission_standard='Euro6d-TEMP', widens
-- secondary_consumption_l100km's CHECK to 0.1-30) -- confirmed already run live, 2026-11-15.
--
-- SCHEMA (research doc section 3, Martin's decision M1): option C. Each REx variant is its
-- own catalog_engines row with fuel_type = 'electric' (so the Costs tab, EV tag rules and EV
-- filters keep treating it as the EV it is) PLUS the generator's own hardware columns
-- (displacement_cc 647, cylinders 'L2', timing_type 'chain', emission_standard,
-- engine_oil_capacity_liters, oil_change_interval_months) and hybrid_type = 'EREV' to mark it
-- explicitly as a range extender. power_kw/torque_nm on the row are the ELECTRIC MOTOR's
-- (same as the matching pure-EV engine) -- the generator's own output (28 kW/56 Nm) has no
-- column under this option and is recorded in pros[] instead.
--
-- REUSE/CREATE summary:
--   engines: 0 REUSE, 6 NEW. Not near-duplicates of the 5 live pure-EV i3 engines
--     (displacement_cc/emission_standard are NULL on every live BEV row and filled here).
--   transmissions: generic:Single-speed EV (i3 I01), already live, same unit as every pure-EV
--     i3 configuration (research doc 2b).
--   body types: 1 REUSE (Hatchback 5-door), 0 NEW.
--   drivetrain systems: none -- RWD, no AWD system.
--   brand/model/phases: all REUSE (BMW / i3 / I01, both phases already live).
--
-- EMISSION-STANDARD SPLIT (CLAUDE.md rule 3; accepted by Martin 2026-11-15 with this seed).
-- ADAC lists the facelift 94 Ah REx (and i3s REx) twice: 11/2017-03/2018 at Euro 6c,
-- 04/2018-09/2018 at Euro 6d-TEMP, every other fact identical -> 2 engine rows and 2
-- otherwise-identical configuration rows per facelift battery/motor combination. Pre-facelift
-- G1/G2: one standard (BMW "EU6" -> 'Euro6') across the whole build run.
--
-- CONFIGURATIONS (research doc section 1, approved by Martin 2026-11-15):
--   G1  Pre-facelift  i3 (60 Ah) REx   125 kW/250 Nm, 18.8 kWh net   11/2013-07/2017
--   G2  Pre-facelift  i3 (94 Ah) REx   125 kW/250 Nm, 27.2 kWh net   07/2016-08/2017
--   G3a Facelift      i3 (94 Ah) REx   125 kW/250 Nm, 27.2 kWh net   11/2017-03/2018 (Euro 6c)
--   G3b Facelift      i3 (94 Ah) REx   125 kW/250 Nm, 27.2 kWh net   04/2018-09/2018 (Euro 6d-T)
--   G4a Facelift      i3s (94 Ah) REx  135 kW/270 Nm, 27.2 kWh net   11/2017-03/2018 (Euro 6c)
--   G4b Facelift      i3s (94 Ah) REx  135 kW/270 Nm, 27.2 kWh net   04/2018-09/2018 (Euro 6d-T)
-- Not seeded (not offered in Europe): a 60 Ah i3s REx, any 120 Ah REx.
--
-- NOT STORED (schema gap, research doc section 3 "Body-level fields"): the REx's own 9-litre
-- fuel tank, higher GVW (1755-1780 kg) and payload (380-415 kg) -- phase_body_dimensions is keyed
-- by (phase_id, body_type_id) only, so setting them there would wrongly apply to the pure EV.
-- curb_weight_kg has a per-configuration column and IS stored below.
--
-- STILL NULL, NOT GUESSED (NULL over invention):
--   yearly_maintenance_eur_min/max on all 6 engines -- 30-65 EUR/year proposed (research doc
--     M8), pending Martin's confirmation.
--   oil_service_cost_eur_min/max -- no SK/CZ independent-workshop figure (R5).
--   engine code (W20K06A EU vs W20K06U0 US, R1), injection_type, has_gpf.
--   ev_range_wltp_km is not written: it is a generated column (= ev_range_km), so it will read
--     the NEDC figure, as on every live pure-EV i3 row. BMW's WLTP range for the facelift REx
--     (R3) has no column of its own.
--
-- FAULTS: every existing engine-level fault on the matching pure-EV engine row is copied onto the
-- matching REx row verbatim (otherwise the REx cars would look more reliable than the BEV). The
-- motor-mount fault (affected_year_to 2015) is not copied onto facelift-built rows. Phase-level
-- faults already cover REx cars via phase_id. Three new REx-only faults (research doc 2e,
-- costs/probabilities from Martin, section 0 M8-M10):
--   F1  fuel-tank vent line recall (EU Safety Gate A12/0428/17), fixed -- G1, G2 only.
--   F2  fuel-tank pressure-temperature sensor (SI B16 03 18), EUR 250-400, 0.02/yr -- G1, G2 only.
--   F3  REx coolant expansion tank leak (SI B17 04 16), EUR 300-500; 0.02/yr pre-facelift,
--       0.005/yr facelift -- every REx row.
--
-- Additive only (new engines, new configurations, new fault rows) -- nothing existing is altered.

begin;

do $$
begin
  if exists (select 1 from catalog_engines where code = 'i3-60Ah-REx' and power_kw = 125) then
    raise exception 'catalog_engines.i3-60Ah-REx (power_kw=125) already exists -- reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'i3-94Ah-REx' and power_kw = 125) then
    raise exception 'catalog_engines.i3-94Ah-REx (power_kw=125) already exists -- reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'i3-94Ah-REx-Euro6c' and power_kw = 125) then
    raise exception 'catalog_engines.i3-94Ah-REx-Euro6c (power_kw=125) already exists -- reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'i3-94Ah-REx-Euro6dT' and power_kw = 125) then
    raise exception 'catalog_engines.i3-94Ah-REx-Euro6dT (power_kw=125) already exists -- reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'i3s-94Ah-REx-Euro6c' and power_kw = 135) then
    raise exception 'catalog_engines.i3s-94Ah-REx-Euro6c (power_kw=135) already exists -- reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'i3s-94Ah-REx-Euro6dT' and power_kw = 135) then
    raise exception 'catalog_engines.i3s-94Ah-REx-Euro6dT (power_kw=135) already exists -- reconcile is stale, re-check before running.';
  end if;
  if not exists (
    select 1 from transmission_units
    where code = 'generic:Single-speed EV (i3 I01)' or 'generic:Single-speed EV (i3 I01)' = any(alt_codes)
  ) then
    raise exception 'No transmission_units row matches ''generic:Single-speed EV (i3 I01)'' -- reconcile is stale, re-check before running.';
  end if;
  if not exists (select 1 from catalog_body_types where name = 'Hatchback 5-door') then
    raise exception 'catalog_body_types.''Hatchback 5-door'' is missing -- reconcile is stale, re-check before running.';
  end if;
  if not exists (
    select 1 from catalog_phases cp
    join catalog_models cm on cm.id = cp.model_id join catalog_brands cb on cb.id = cm.brand_id
    where cb.name = 'BMW' and cm.name = 'i3' and cp.generation_code = 'I01' and cp.phase_label = 'Pre-facelift'
  ) then
    raise exception 'BMW i3 (I01) Pre-facelift phase is missing -- reconcile is stale, re-check before running.';
  end if;
  if not exists (
    select 1 from catalog_phases cp
    join catalog_models cm on cm.id = cp.model_id join catalog_brands cb on cb.id = cm.brand_id
    where cb.name = 'BMW' and cm.name = 'i3' and cp.generation_code = 'I01' and cp.phase_label = 'Facelift'
  ) then
    raise exception 'BMW i3 (I01) Facelift phase is missing -- reconcile is stale, re-check before running.';
  end if;
end $$;

