with
  phase_lookup as (
    select cp.id, cp.phase_label
    from catalog_phases cp
    join catalog_models cm on cm.id = cp.model_id
    join catalog_brands cb on cb.id = cm.brand_id
    where cb.name = 'BMW' and cm.name = 'i3' and cp.generation_code = 'I01'
  ),
  body_lookup as (select id, name from catalog_body_types where name = 'Hatchback 5-door'),
  engine_lookup as (
    select id, code, power_kw from catalog_engines
    where code in ('i3-60Ah-REx', 'i3-94Ah-REx', 'i3-94Ah-REx-Euro6c', 'i3-94Ah-REx-Euro6dT', 'i3s-94Ah-REx-Euro6c', 'i3s-94Ah-REx-Euro6dT')
  ),
  unit_lookup as (
    select id, code, alt_codes from transmission_units
    where code = 'generic:Single-speed EV (i3 I01)'
  ),
  configs (
    phase_label, engine_code, engine_power_kw, driven_axle,
    consumption_cycle, energy_consumption_kwh100km, secondary_fuel_type, secondary_consumption_l100km,
    co2_emissions_g_km, ev_range_km, ev_range_wltp_km, curb_weight_kg, acceleration_0_100, top_speed_kmh
  ) as (
    values
      ('Pre-facelift'::text, 'i3-60Ah-REx'::text, 125::integer, 'rear'::text,
       'NEDC'::text, 13.5::numeric, 'petrol'::text, 0.6::numeric,
