       13::integer, 235::integer, null::integer, 1440::integer, 8.1::numeric, 150::integer),
      ('Facelift'::text, 'i3-94Ah-REx-Euro6dT'::text, 125::integer, 'rear'::text,
       'NEDC'::text, 11.5::numeric, 'petrol'::text, 0.6::numeric,
