       14::integer, 220::integer, null::integer, 1460::integer, 7.7::numeric, 160::integer)
  )
insert into catalog_vehicle_configurations (
  phase_id, body_type_id, engine_id, unit_id, drivetrain_id, driven_axle,
  fuel_consumption_l100km, energy_consumption_kwh100km, consumption_cycle,
  secondary_fuel_type, secondary_consumption_l100km,
  co2_emissions_g_km, ev_range_km, curb_weight_kg, acceleration_0_100, top_speed_kmh
)
-- ev_range_wltp_km is a GENERATED column (= ev_range_km) and cannot be written; the reviewed
-- draft listed it here and the first run failed on it (rolled back, nothing written). The
-- configs CTE still carries the NULL for documentation only.
select
  p.id, b.id, e.id, u.id, null::uuid, c.driven_axle,
  null::numeric, c.energy_consumption_kwh100km, c.consumption_cycle,
  c.secondary_fuel_type, c.secondary_consumption_l100km,
  c.co2_emissions_g_km, c.ev_range_km, c.curb_weight_kg, c.acceleration_0_100, c.top_speed_kmh
from configs c
join phase_lookup p on p.phase_label = c.phase_label
join body_lookup b on true
join engine_lookup e on e.code = c.engine_code and e.power_kw = c.engine_power_kw
join unit_lookup u on true
on conflict (
  phase_id, body_type_id, engine_id, unit_id,
  coalesce(drivetrain_id, '00000000-0000-0000-0000-000000000000'::uuid)
) do nothing;

-- ════════════════════════════════════════════════════════════
-- 3. COMPONENT FAULTS
--    3a. Copied verbatim from the matching pure-EV engine row.
-- ════════════════════════════════════════════════════════════

with
  rex_engines as (
    select id, code from catalog_engines
    where code in ('i3-60Ah-REx', 'i3-94Ah-REx', 'i3-94Ah-REx-Euro6c', 'i3-94Ah-REx-Euro6dT', 'i3s-94Ah-REx-Euro6c', 'i3s-94Ah-REx-Euro6dT')
  ),
  copy_map (source_code, source_power_kw, target_code) as (
    values
      ('i3-60Ah'::text, 125::integer, 'i3-60Ah-REx'::text),
      ('i3-94Ah'::text, 125::integer, 'i3-94Ah-REx'::text),
      ('i3-94Ah'::text, 125::integer, 'i3-94Ah-REx-Euro6c'::text),
      ('i3-94Ah'::text, 125::integer, 'i3-94Ah-REx-Euro6dT'::text),
      ('i3s-94Ah'::text, 135::integer, 'i3s-94Ah-REx-Euro6c'::text),
      ('i3s-94Ah'::text, 135::integer, 'i3s-94Ah-REx-Euro6dT'::text)
  ),
  source_faults as (
    select ccf.fault, ccf.severity, ccf.estimated_cost_eur_min, ccf.estimated_cost_eur_max,
           ccf.annual_probability, ccf.affected_year_from, ccf.affected_year_to, ccf.pre_purchase_check,
           ce.code as source_code, ce.power_kw as source_power_kw
    from catalog_component_faults ccf
    join catalog_engines ce on ce.id = ccf.engine_id
    where ccf.component_type = 'engine'
      and (ce.code, ce.power_kw) in (('i3-60Ah', 125), ('i3-94Ah', 125), ('i3s-94Ah', 135))
  )
insert into catalog_component_faults (component_type, engine_id, fault, severity, estimated_cost_eur_min, estimated_cost_eur_max, annual_probability, affected_year_from, affected_year_to, pre_purchase_check)
select 'engine', re.id, sf.fault, sf.severity, sf.estimated_cost_eur_min, sf.estimated_cost_eur_max, sf.annual_probability, sf.affected_year_from, sf.affected_year_to, sf.pre_purchase_check
from copy_map cm
join source_faults sf on sf.source_code = cm.source_code and sf.source_power_kw = cm.source_power_kw
join rex_engines re on re.code = cm.target_code
where not (
  -- the motor-mount fault (affected_year_to 2015) was authored for pre-facelift cars only; it is
  -- not copied onto a facelift-built target (built from 11/2017).
  sf.fault like '%motor mount%' and cm.target_code not in ('i3-60Ah-REx', 'i3-94Ah-REx')
)
and not exists (
  select 1 from catalog_component_faults ccf2 where ccf2.engine_id = re.id and ccf2.fault = sf.fault
);

-- 3b. New REx-only faults F1-F3 (research doc section 2e, costs/probabilities section 0 M8-M10).

with rex_engines as (
  select id, code from catalog_engines
  where code in ('i3-60Ah-REx', 'i3-94Ah-REx', 'i3-94Ah-REx-Euro6c', 'i3-94Ah-REx-Euro6dT', 'i3s-94Ah-REx-Euro6c', 'i3s-94Ah-REx-Euro6dT')
),
new_faults (target_code, fault, severity, cost_min, cost_max, prob, yr_from, yr_to, check_text) as (
  values
    -- F1: fixed recall, G1 and G2 only (built 09/2013-12/2016; facelift starts 11/2017)
    ('i3-60Ah-REx'::text,
     'Recall: fuel-tank ventilation line routed against the battery (B+) cable in the REx engine bay can chafe through and leak petrol vapour -- fire risk (EU Safety Gate A12/0428/17). Fixed free of charge under the campaign: BMW checks for contact, replaces the vent line if needed, and fits a spacer.'::text,
     'critical'::text, null::numeric, null::numeric, null::numeric, 2013::integer, 2016::integer,
     'Confirm the recall was carried out (BMW VIN check).'::text),
    ('i3-94Ah-REx'::text,
     'Recall: fuel-tank ventilation line routed against the battery (B+) cable in the REx engine bay can chafe through and leak petrol vapour -- fire risk (EU Safety Gate A12/0428/17). Fixed free of charge under the campaign: BMW checks for contact, replaces the vent line if needed, and fits a spacer.'::text,
     'critical'::text, null::numeric, null::numeric, null::numeric, 2013::integer, 2016::integer,
     'Confirm the recall was carried out (BMW VIN check).'::text),
    -- F2: fuel-tank pressure-temperature sensor, G1 and G2 only (built 03/2014-04/2017)
    ('i3-60Ah-REx'::text,
     'Fuel-tank pressure-temperature sensor: its internal seal fails, the sensor reads wrong and sets an evaporative-system fault -- engine warning light. Fix: new sensor (BMW part 16 14 7 426 661); the tank has to be drained and refilled for the job.'::text,
     'moderate'::text, 250::numeric, 400::numeric, 0.02::numeric, 2014::integer, 2017::integer,
     'Ask whether the sensor was replaced (service history).'::text),
    ('i3-94Ah-REx'::text,
     'Fuel-tank pressure-temperature sensor: its internal seal fails, the sensor reads wrong and sets an evaporative-system fault -- engine warning light. Fix: new sensor (BMW part 16 14 7 426 661); the tank has to be drained and refilled for the job.'::text,
     'moderate'::text, 250::numeric, 400::numeric, 0.02::numeric, 2014::integer, 2017::integer,
     'Ask whether the sensor was replaced (service history).'::text),
    -- F3: REx coolant expansion tank, every REx row, rate depends on pre-facelift vs facelift
    ('i3-60Ah-REx'::text,
     'REx coolant expansion tank (or its hoses) leaks -- engine warning light and "Drivetrain: only electric drive possible, limited driving range"; the range extender is shut off until repaired. Fix: new expansion tank / hoses, bleed the circuit, test-run the REx for overheat damage.'::text,
     'moderate'::text, 300::numeric, 500::numeric, 0.02::numeric, null::integer, null::integer,
     'Look for coolant traces at the REx expansion tank (under the luggage-area service cover).'::text),
    ('i3-94Ah-REx'::text,
     'REx coolant expansion tank (or its hoses) leaks -- engine warning light and "Drivetrain: only electric drive possible, limited driving range"; the range extender is shut off until repaired. Fix: new expansion tank / hoses, bleed the circuit, test-run the REx for overheat damage.'::text,
     'moderate'::text, 300::numeric, 500::numeric, 0.02::numeric, null::integer, null::integer,
     'Look for coolant traces at the REx expansion tank (under the luggage-area service cover).'::text),
    ('i3-94Ah-REx-Euro6c'::text,
     'REx coolant expansion tank (or its hoses) leaks -- engine warning light and "Drivetrain: only electric drive possible, limited driving range"; the range extender is shut off until repaired. Fix: new expansion tank / hoses, bleed the circuit, test-run the REx for overheat damage.'::text,
     'moderate'::text, 300::numeric, 500::numeric, 0.005::numeric, null::integer, null::integer,
     'Look for coolant traces at the REx expansion tank (under the luggage-area service cover).'::text),
    ('i3-94Ah-REx-Euro6dT'::text,
     'REx coolant expansion tank (or its hoses) leaks -- engine warning light and "Drivetrain: only electric drive possible, limited driving range"; the range extender is shut off until repaired. Fix: new expansion tank / hoses, bleed the circuit, test-run the REx for overheat damage.'::text,
     'moderate'::text, 300::numeric, 500::numeric, 0.005::numeric, null::integer, null::integer,
     'Look for coolant traces at the REx expansion tank (under the luggage-area service cover).'::text),
    ('i3s-94Ah-REx-Euro6c'::text,
     'REx coolant expansion tank (or its hoses) leaks -- engine warning light and "Drivetrain: only electric drive possible, limited driving range"; the range extender is shut off until repaired. Fix: new expansion tank / hoses, bleed the circuit, test-run the REx for overheat damage.'::text,
     'moderate'::text, 300::numeric, 500::numeric, 0.005::numeric, null::integer, null::integer,
     'Look for coolant traces at the REx expansion tank (under the luggage-area service cover).'::text),
    ('i3s-94Ah-REx-Euro6dT'::text,
     'REx coolant expansion tank (or its hoses) leaks -- engine warning light and "Drivetrain: only electric drive possible, limited driving range"; the range extender is shut off until repaired. Fix: new expansion tank / hoses, bleed the circuit, test-run the REx for overheat damage.'::text,
     'moderate'::text, 300::numeric, 500::numeric, 0.005::numeric, null::integer, null::integer,
     'Look for coolant traces at the REx expansion tank (under the luggage-area service cover).'::text)
)
insert into catalog_component_faults (component_type, engine_id, fault, severity, estimated_cost_eur_min, estimated_cost_eur_max, annual_probability, affected_year_from, affected_year_to, pre_purchase_check)
select 'engine', re.id, nf.fault, nf.severity, nf.cost_min, nf.cost_max, nf.prob, nf.yr_from, nf.yr_to, nf.check_text
from new_faults nf
join rex_engines re on re.code = nf.target_code
where not exists (
  select 1 from catalog_component_faults ccf where ccf.engine_id = re.id and ccf.fault = nf.fault
);

-- ════════════════════════════════════════════════════════════
-- 4. POST-CONDITION ASSERTIONS
-- ════════════════════════════════════════════════════════════

do $$
declare
  engine_n integer;
  config_n integer;
  fault_n integer;
begin
  select count(*) into engine_n from catalog_engines
  where code in ('i3-60Ah-REx', 'i3-94Ah-REx', 'i3-94Ah-REx-Euro6c', 'i3-94Ah-REx-Euro6dT', 'i3s-94Ah-REx-Euro6c', 'i3s-94Ah-REx-Euro6dT');
  if engine_n <> 6 then
    raise exception 'Expected 6 REx engine rows, found %.', engine_n;
  end if;

  select count(*) into config_n
  from catalog_vehicle_configurations cvc
  join catalog_engines ce on ce.id = cvc.engine_id
  where ce.code in ('i3-60Ah-REx', 'i3-94Ah-REx', 'i3-94Ah-REx-Euro6c', 'i3-94Ah-REx-Euro6dT', 'i3s-94Ah-REx-Euro6c', 'i3s-94Ah-REx-Euro6dT');
  if config_n <> 6 then
    raise exception 'Expected 6 REx configurations, found %.', config_n;
  end if;

  select count(*) into fault_n
  from catalog_component_faults ccf
  join catalog_engines ce on ce.id = ccf.engine_id
  where ce.code in ('i3-60Ah-REx', 'i3-94Ah-REx', 'i3-94Ah-REx-Euro6c', 'i3-94Ah-REx-Euro6dT', 'i3s-94Ah-REx-Euro6c', 'i3s-94Ah-REx-Euro6dT');
  if fault_n <> 28 then
    raise exception 'Expected 28 REx fault rows (copied + new F1-F3), found %.', fault_n;
  end if;
end $$;

commit;
